@Service
public class KafkaOrderProducer {

    private final KafkaTemplate<String, OrderEvent> kafkaTemplate;

    public KafkaOrderProducer(KafkaTemplate<String, OrderEvent> kafkaTemplate) {
        this.kafkaTemplate = kafkaTemplate;
    }

    public void publishOrder(OrderEvent event) {
        // Keying by customerId ensures all events for the same customer land in the exact same partition, preserving order
        CompletableFuture<SendResult<String, OrderEvent>> future = 
            kafkaTemplate.send("order-events-topic", event.getCustomerId(), event);

        future.whenComplete((result, ex) -> {
            if (ex == null) {
                System.out.println("Produced event to partition: " + result.getRecordMetadata().partition() + ", offset: " + result.getRecordMetadata().offset());
            } else {
                handleFailure(ex);
            }
        });
    }

    private void handleFailure(Throwable ex) {
        // Implement retry logic or write to dead-letter sink
    }
}
